// Analyze error and determine retryability
const execution = $input.first().json.execution || {};
const workflow = $input.first().json.workflow || {};
const error = execution.error || {};

const errorMessage = error.message || 'Unknown automation execution failure';
const httpCode = error.httpCode || error.statusCode || null;

// Transient network/infrastructure errors are retryable
const isRetryable = (
  httpCode === 502 ||
  httpCode === 503 ||
  httpCode === 504 ||
  errorMessage.includes('ECONNREFUSED') ||
  errorMessage.includes('ETIMEDOUT') ||
  errorMessage.includes('socket hang up')
);

return [{
  json: {
    workflow_name: workflow.name || 'CareFlow Workflow',
    workflow_id: workflow.id,
    execution_id: execution.id,
    failed_node: execution.lastNodeExecuted || 'Unknown Node',
    error_message: errorMessage,
    http_status: httpCode,
    is_retryable: isRetryable,
    suggested_action: isRetryable 
      ? 'Transient network failure: schedule exponential backoff retry.'
      : 'Non-retryable application/validation error: investigate payload and backend logs.',
    timestamp: new Date().toISOString()
  }
}];

// Format retry notification
const data = $input.first().json;
return [{
  json: {
    event: 'AUTOMATION_ERROR_RETRYABLE',
    alert_level: 'WARNING',
    workflow: data.workflow_name,
    failed_node: data.failed_node,
    message: data.error_message,
    action: data.suggested_action,
    timestamp: data.timestamp
  }
}];

// Format fatal ops alert
const data = $input.first().json;
return [{
  json: {
    event: 'AUTOMATION_ERROR_FATAL',
    alert_level: 'CRITICAL',
    workflow: data.workflow_name,
    failed_node: data.failed_node,
    message: data.error_message,
    http_status: data.http_status,
    action: data.suggested_action,
    timestamp: data.timestamp
  }
}];
